package com.kartyavya.report.service; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.util.*; @Service public class FileStorageService{@Value("${storage.root:./uploads}")String root;private static final Set<String> TYPES=Set.of("image/jpeg","image/png","image/webp");public String save(MultipartFile f,String folder){if(f==null||f.isEmpty())throw new IllegalArgumentException("Image is required");if(f.getSize()>5*1024*1024)throw new IllegalArgumentException("Image size cannot exceed 5 MB");if(!TYPES.contains(f.getContentType()))throw new IllegalArgumentException("Only JPG, PNG and WEBP images are allowed");try{byte[] head=f.getInputStream().readNBytes(12);boolean jpg=head.length>=3&&(head[0]&255)==255&&(head[1]&255)==216&&(head[2]&255)==255;boolean png=head.length>=8&&(head[0]&255)==137&&head[1]==80&&head[2]==78&&head[3]==71;boolean webp=head.length>=12&&new String(head,0,4).equals("RIFF")&&new String(head,8,4).equals("WEBP");if(!(jpg||png||webp))throw new IllegalArgumentException("The uploaded file is not a valid image");String ext=jpg?".jpg":png?".png":".webp";Path dir=Paths.get(root,folder).toAbsolutePath().normalize();Files.createDirectories(dir);String name=UUID.randomUUID().toString().replace("-","")+ext;Files.copy(f.getInputStream(),dir.resolve(name),StandardCopyOption.REPLACE_EXISTING);return "/uploads/"+folder+"/"+name;}catch(IOException e){throw new IllegalStateException("Unable to store image",e);}}}
